mapper.select:
SELECT q.id AS quiz_id, q.title, q.description, q.start_time, q.end_time, q.total_score, q.attempt_limit, q.status, (SELECT COUNT(*) FROM quiz_questions qq WHERE qq.quiz_id = q.id) AS question_count FROM quizzes q WHERE q.course_id = #{courseId}
AND q.status = 'published' AND (q.start_time IS NULL OR q.start_time <= NOW()) AND (q.end_time IS NULL OR q.end_time >= NOW())
ORDER BY q.created_at DESC LIMIT #{limit} OFFSET #{offset}
